import type { BlogArticleFaq} from '../../../types/blog';
export const BODY: string = "\n<p>চাকরির পোর্টাল আর আবেদনের ফরম ছবি নিয়ে খুব খুঁতখুঁতে৤ তারা ফাইলের আকারের সীমা, মাপের নিয়ম আর ফরম্যাটের তালিকা দেয়, তারপর যা ভাঙে তা বাতিল করে দেয়৤</p>\n<p>এই সিস্টেমগুলোতে ছবি আর নথির জন্য দুইশ কিলোবাইট সবচেয়ে সাধারণ সীমা৤ এটা তীক্ষ্ণ ছবির জন্য যথেষ্ট উদার আর সার্ভার দ্রুত রাখার জন্য যথেষ্ট কঠোর৤</p>\n<p>এই লেখায় দেখানো হয়েছে কীভাবে 200KB ছবি তৈরি করবেন যা চাকরির পোর্টাল আর ফরমে প্রথম চেষ্টাতেই পাস করে৤</p>\n<h2 id=\"why-portals-use-200kb\">চাকরির পোর্টাল কেন 200KB সীমা দেয়</h2>\n<p>চাকরির পোর্টালে লাখ লাখ আবেদন জমা হয়৤ প্রতিটি ছবি 5MB হলে স্টোরেজ আর ব্যান্ডউইথের খরচ বিশাল হয়ে যেত৤</p>\n<p>200KB সীমা সিস্টেম দ্রুত রাখে৤ নিয়োগকর্তারা একটার পর একটা ডজনখানেক প্রোফাইল খুলতে পারেন, ভারী ছবি লোড হওয়ার অপেক্ষা ছাড়াই৤</p>\n<p>সীমাটা ন্যায্যতাও রাখে৤ প্রতিটি আবেদনকারী একই বাজেট পান, তাই ভারী ফাইল দিয়ে কেউ সুবিধা পান না৤</p>\n<p>সবশেষে, কাজের জন্য 200KB যথেষ্ট৤ নিয়োগকর্তার পরিষ্কার মুখ আর পড়া যায় এমন নথি দরকার, প্রিন্টের মানের ছবি নয়৤</p>\n<p>কারণটা বুঝলে সীমা মেনে নেওয়া সহজ হয়৤ এটা আপনাকে বিরক্ত করতে নয়, সবার জন্য সিস্টেম চালু রাখতেই আছে৤</p>\n<h2 id=\"profile-photo-rules\">চাকরির পোর্টালে প্রোফাইল ছবির নিয়ম</h2>\n<p>বেশিরভাগ পোর্টাল সাদা পটভূমিতে সাম্প্রতিক হেডশট চায়৤ মুখ সামনের দিকে, ভালো আলোয় আর ফ্রেমের মাঝখানে থাকা উচিত৤</p>\n<p>ফাইলের আকারের পাশাপাশি মাপও অনেক সময় বলা থাকে৤ 200KB সর্বোচ্চ আর 600 বাই 600 পিক্সেলের সুপারিশ—এই জোড়াটা খুব সাধারণ৤</p>\n<p>ফরম্যাট সাধারণত JPG আর PNG-তেই সীমিত৤ WebP খুব কমই তালিকায় থাকে, তাই নিয়ম অন্য কিছু না বললে পোর্টালের ছবিতে JPG ব্যবহার করুন৤</p>\n<p>পোর্টাল আপনার ছবি বৃত্তে কাটে কি না দেখে নিন৤ কাটলে মুখ মাঝখানে রাখুন আর চারপাশে জায়গা রাখুন, নইলে প্রান্ত কেটে যাবে৤</p>\n<p>আপলোডের পর ছবির প্রিভিউ দেখুন৤ বেশিরভাগ পোর্টাল নিয়োগকর্তার কাছে কেমন দেখাবে তা দেখায়, আর সমস্যা ঠিক করার সেটাই শেষ সুযোগ৤</p>\n<h2 id=\"resume-documents\">জীবনবৃত্তান্ত, সার্টিফিকেট আর নথির স্ক্যান</h2>\n<p>নথিতেও ছবির মতো 200KB সীমা থাকে, কিন্তু আচরণ আলাদা৤ স্ক্যান করা সার্টিফিকেট বেশিরভাগই সাদা জায়গা, তাই সহজে কমপ্রেস হয়৤</p>\n<p>সেরা ভারসাম্যের জন্য 300 DPI-তে স্ক্যান করুন৤ বেশি রেজোলিউশনে বিশাল ফাইল হয়, আর কম রেজোলিউশনে লেখা ঝাপসা হয়৤</p>\n<p>কমপ্রেসের পর সবচেয়ে ছোট লেখাটা প্রিভিউ করুন৤ রেজিস্ট্রেশন নম্বর, তারিখ আর স্বাক্ষরই প্রথমে ক্ষতিগ্রস্ত হয়৤</p>\n<p>নথিতে ছবি থাকলে ছবিটাই কঠিনতা ঠিক করে৤ প্রতিকৃতিসহ সার্টিফিকেট সাধারণ লেখার পাতার চেয়ে বেশি যত্ন চায়৤</p>\n<p>প্রতিটি নথির উচ্চ রেজোলিউশনের কপি রেখে দিন৤ পোর্টাল পরে বড় সংস্করণ চাইতে পারে, আর 200KB ফাইল পরিষ্কারভাবে বড় করা যায় না৤</p>\n<h2 id=\"signature-rules\">ফরমের জন্য স্বাক্ষরের ছবি</h2>\n<p>অনেক ফরম ছবির পাশাপাশি স্ক্যান করা স্বাক্ষর চায়৤ স্বাক্ষর দারুণভাবে কমপ্রেস হয়, কারণ এর বেশিরভাগটাই ফাঁকা জায়গা৤</p>\n<p>সাদা কাগজে গাঢ় কলমে স্বাক্ষর করুন৤ হালকা পেনসিলের দাগের চেয়ে মোটা, গাঢ় স্বাক্ষর কমপ্রেশনে অনেক ভালো টিকে থাকে৤</p>\n<p>স্বাক্ষর সোজাসুজি স্ক্যান করুন বা ছবি তুলুন৤ বাঁকা স্বাক্ষর ফাঁকা কোণে পিক্সেল নষ্ট করে আর অপেশাদার দেখাতে পারে৤</p>\n<p>কমপ্রেসের আগে স্বাক্ষরের চারপাশ টাইট করে ক্রপ করুন৤ ফাঁকা মার্জিন সরিয়ে দিলে 200KB বাজেটের বেশি অংশ স্বাক্ষরের জন্য থাকে৤</p>\n<p>ফল পুরো আকারে দেখে নিন৤ স্বাক্ষর কাগজে কালির মতো দেখানো উচিত, ধূসর ছোপের মতো নয়৤</p>\n<h2 id=\"format-choice-portals\">পোর্টালের জন্য ফরম্যাট বেছে নেওয়া</h2>\n<p>পোর্টালে আপলোডের জন্য JPG সবচেয়ে নিরাপদ ফরম্যাট৤ প্রতিটি চাকরির পোর্টাল এটা নেয়, আর 200KB-তে এর কোয়ালিটি চমৎকার৤</p>\n<p>PNG বেশিরভাগ পোর্টাল নিলেও ছবির জন্য খারাপ পছন্দ৤ PNG-তে ছবি 200KB-তে পৌঁছাতে মাপ অনেক কমাতে হতে পারে৤</p>\n<p>চাকরির পোর্টালে WebP খুব কমই নেওয়া হয়৤ দেখতে ভালো হলেও বাতিল হওয়া ফাইল অকেজো, তাই নিয়মে WebP না থাকলে ঝুঁকি নেবেন না৤</p>\n<p>নথিতেও সাধারণত JPG-ই জেতে৤ 200KB-তে JPG-তে স্ক্যান করা সার্টিফিকেট পড়া যায়, আর PNG-তে বসাতে মাপ ছোট করতে হতে পারে৤</p>\n<p>নিয়ম অস্পষ্ট থাকলে JPG আপলোড করুন৤ পোর্টালগুলো এই ফরম্যাটকে ঘিরেই তৈরি, আর এতে কখনো সামঞ্জস্যের সমস্যা হয় না৤</p>\n<h2 id=\"step-by-step-portal\">ধাপে ধাপে: পোর্টালের ছবি তৈরি করা</h2>\n<p>ভালো আলো আর সাদা পটভূমিতে নতুন হেডশট তুলুন৤ আজ তোলা ছবি পাঁচ বছর আগের ছবির চেয়ে সবদিকেই ভালো৤</p>\n<p><a href=\"/bn/image-200kb-te-compress-korun\">200KB কমপ্রেসর</a> খুলে অরিজিনাল আপলোড করুন৤ আউটপুট ফরম্যাট JPG রাখুন৤</p>\n<p>200KB-র নিচে বসে এমন সেরা কোয়ালিটি বাইনারি সার্চকে খুঁজতে দিন৤ পুরো আকারে মুখের প্রিভিউ দেখুন, চোখ আর প্রান্ত যাচাই করুন৤</p>\n<p>ফাইল ডাউনলোড করে আকার দেখে নিন৤ এটা 200KB-র একটু নিচে থাকা উচিত, সাধারণত 198KB থেকে 199.9KB-র মধ্যে৤</p>\n<p>পোর্টালে আপলোড করে প্রিভিউ দেখে নিন৤ মুখ মাঝখানে আছে কি না, ছবি সোজা আছে কি না, আর কিছু কাটা পড়েছে কি না নিশ্চিত করুন৤</p>\n<h2 id=\"common-rejections\">সাধারণ বাতিলের কারণ আর সমাধান</h2>\n<p>ফাইল অনেক বড়—এটাই সবচেয়ে সাধারণ বাতিলের কারণ৤ সমাধান কমপ্রেশন, তবে আগে সঠিক সীমা দেখে নিন, কারণ কিছু পোর্টাল 200KB নয়, 100KB-তে সীমা দেয়৤</p>\n<p>ভুল ফরম্যাট দ্বিতীয় সবচেয়ে সাধারণ কারণ৤ শুধু JPG নেওয়া পোর্টালে WebP ফাইল সঙ্গে সঙ্গে বাতিল হয়, তাই আপলোডের আগে JPG-তে বদলে নিন৤</p>\n<p>ভুল মাপও বাতিলের কারণ হয়৤ পোর্টাল 600 বাই 600 পিক্সেল চাইলে অন্য মাপের 200KB ফাইলও বাতিল হয়৤</p>\n<p>ঝাপসা বা অন্ধকার ছবি মানুষের পরীক্ষক বাতিল করেন৤ কমপ্রেশন খারাপ সোর্স ঠিক করতে পারে না, তাই ভালো আলোয় ছবি আবার তুলুন৤</p>\n<p>প্রতিবার সঠিক ত্রুটির বার্তাটা পড়ুন৤ কোন নিয়ম ভেঙেছে তা এটা বলে দেয়, আর প্রতিটি নিয়মের সমাধান আলাদা৤</p>\n<h2 id=\"multiple-documents\">একসঙ্গে অনেক নথি সামলানো</h2>\n<p>একটা আবেদনে ছবি, স্বাক্ষর, জীবনবৃত্তান্ত আর দুটো সার্টিফিকেট লাগতে পারে৤ একটা একটা করে কমপ্রেস করা ধীর৤</p>\n<p>ব্যাচ মোডে সব একসঙ্গে 200KB-তে কমপ্রেস করুন৤ প্রতিটি ফাইল একই লক্ষ্যে প্রসেস হয় আর ZIP হিসেবে ডাউনলোড হয়৤</p>\n<p>এক্সট্রাক্টের পর প্রতিটি ফাইল দেখে নিন৤ স্বাক্ষর আর প্রতিকৃতির চাহিদা আলাদা, আর একটায় অন্য সেটিংয়ে আবার চেষ্টা লাগতে পারে৤</p>\n<p>আপলোডের আগে ফাইলগুলোর পরিষ্কার নাম দিন৤ resume-200kb.jpg-এর মতো নাম একই রকম নথি গুলিয়ে ফেলা থেকে বাঁচায়৤</p>\n<p>একটা একটা করে আপলোড করুন আর প্রতিটি নিশ্চিত করুন৤ পোর্টাল ছবি নিলেও সার্টিফিকেট বাতিল করতে পারে, আর প্রতিটির আলাদা যাচাই দরকার৤</p>\n<h2 id=\"mobile-applications\">ফোন থেকে আবেদন করা</h2>\n<p>বেশিরভাগ চাকরির আবেদন এখন ফোনেই হয়৤ কাজের ধারা একই, শুধু ফোনের জন্য কয়েকটা টিপস আছে৤</p>\n<p>গ্যালারি থেকে অরিজিনাল ছবিটা বেছে নিন, চ্যাট অ্যাপ থেকে সংরক্ষণ করা কপি নয়৤ চ্যাট অ্যাপ আপনার দেখার আগেই ছবি ছোট করে ফেলে৤</p>\n<p>আইফোনের ছবি HEIC ফাইল হতে পারে৤ সরাসরি টুলে আপলোড করুন, কমপ্রেশনের সময় এটা কনভার্ট সামলে নেয়৤</p>\n<p>ডাউনলোডের পর ফাইলস অ্যাপে ফাইলটা দেখে নিন৤ পোর্টালে ফেরার আগে আকার 200KB-র নিচে আছে কি না নিশ্চিত করুন৤</p>\n<p>পোর্টাল অন্য ট্যাবে খোলা রাখুন৤ ফরম নতুন করে পূরণ করার চেয়ে টুল আর পোর্টালের মধ্যে বদলানো সহজ৤</p>\n<h2 id=\"after-submission\">জমা দেওয়ার পর: কী রাখবেন</h2>\n<p>জমা দেওয়া কমপ্রেস করা ফাইলগুলো রেখে দিন৤ পোর্টাল আবার আপলোড করতে বললে হুবহু ফাইলগুলো তৈরি থাকবে৤</p>\n<p>অরিজিনালগুলোও রেখে দিন৤ ভবিষ্যতের আবেদনে অন্য নিয়ম থাকতে পারে, আর শুধু অরিজিনাল থেকেই নতুন করে কমপ্রেস করা যায়৤</p>\n<p>নিশ্চিতকরণের পেজ বা ইমেইলের কপি সংরক্ষণ করুন৤ এটা প্রমাণ করে আবেদন জমা হয়েছে, তারিখ আর রেফারেন্স নম্বরসহ৤</p>\n<p>কোন সেটিং কাজ করেছে তা লিখে রাখুন৤ পোর্টাল X JPG 200KB-তে নেয়—এমন ছোট নোট পরের আবেদনে সময় বাঁচায়৤</p>\n<p>ভালো রেকর্ড চাপের প্রক্রিয়াকে রুটিনে বদলে দেয়৤ পরের আবেদন ঘণ্টার বদলে মিনিটে শেষ হয়৤</p>\n<h2 id=\"beyond-200kb\">পোর্টাল অন্য আকার চাইলে</h2>\n<p>কিছু পোর্টাল 200KB নয়, 50KB বা 100KB-তে সীমা দেয়৤ সেক্ষেত্রে প্রয়োজন অনুযায়ী <a href=\"/bn/image-50kb-te-compress-korun\">50KB কমপ্রেসর</a> বা <a href=\"/bn/image-100kb-te-compress-korun\">100KB কমপ্রেসর</a> ব্যবহার করুন৤</p>\n<p>অন্যগুলো 500KB বা তার বেশি দেয়৤ সীমা উদার হলে সেরা কোয়ালিটির জন্য <a href=\"/bn/image-500kb-te-compress-korun\">500KB কমপ্রেসর</a> ব্যবহার করুন৤</p>\n<p>কাস্টম সীমায় <a href=\"/bn/target-file-size-compressor\">টার্গেট ফাইল সাইজ কমপ্রেসর</a> লাগে৤ পোর্টাল যে সংখ্যা চায় সেটা টাইপ করুন, আর সেরা কোয়ালিটি খুঁজতে দিন৤</p>\n<p>নীতি কখনো বদলায় না: পোর্টাল যত বড় আকার দেয়, সেটাই ব্যবহার করুন৤ বাড়তি কিলোবাইট পাওয়া গেলে কোয়ালিটির দাম আছে৤</p>\n<h2 id=\"photo-day\">ছবি তোলার দিনের প্রস্তুতি</h2>\n<p>সেরা পোর্টাল ছবি ক্যামেরা বের করার আগেই শুরু হয়৤ সাদা, হালকা রঙের দেয়াল বেছে নিন আর কঠোর ছায়া এড়াতে এক ধাপ দূরে দাঁড়ান৤</p>\n<p>জানালা বা উজ্জ্বল বাতির দিকে মুখ করুন৤ সামনের আলো মুখ সমানভাবে ভরে দেয়, আর পেছনের আলো মুখকে ছায়ামূর্তি বানিয়ে ফেলে৤</p>\n<p>একরঙা, মাঝারি রঙের টপ পরুন৤ ব্যস্ত প্যাটার্ন চোখ সরিয়ে নেয় আর কিলোবাইট খায়, আর একরঙা মুখের দিকে মনোযোগ ধরে রাখে৤</p>\n<p>কয়েকটা শট তুলে সবচেয়ে তীক্ষ্ণটা বেছে নিন৤ ফোকাসের সামান্য পার্থক্য 200KB-তে বেশিরভাগ মানুষের ধারণার চেয়ে বেশি গুরুত্বপূর্ণ৤</p>\n<p>কমপ্রেসের আগে বড় স্ক্রিনে ছবি দেখে নিন৤ ফোনের স্ক্রিনে ভালো লাগা মুখ ল্যাপটপে সমস্যা দেখাতে পারে৤</p>\n<h2 id=\"document-checklist\">আবেদনের জন্য নথির চেকলিস্ট</h2>\n<p>শুরু করার আগে আবেদনে প্রয়োজনীয় প্রতিটি নথি তালিকা করুন৤ ছবি, স্বাক্ষর, জীবনবৃত্তান্ত আর সার্টিফিকেট—এটাই সাধারণ সেট৤</p>\n<p>প্রতিটির নিয়ম আলাদাভাবে দেখুন৤ ছবি 200KB-তে সীমিত থাকলেও সার্টিফিকেট 100KB-তে সীমিত থাকতে পারে, আর গুলিয়ে ফেললে বাতিল হয়৤</p>\n<p>পরিষ্কার স্ক্যানার বেডে 300 DPI-তে নথি স্ক্যান করুন৤ ধুলো আর ছায়া এমন নয়েজ যোগ করে যা কিছু না কিছুর জন্য কিলোবাইট নষ্ট করে৤</p>\n<p>প্রতিটি নথি নিজের সীমায় কমপ্রেস করুন৤ ব্যাচ মোডে আলাদা ফাইল চলে, কিন্তু প্রতিটি ফাইলের পরে আলাদা যাচাই দরকার৤</p>\n<p>আপলোড করার সঙ্গে সঙ্গে প্রতিটি নথিতে টিক দিন৤ চেকলিস্ট চাপের আবেদনকে শান্ত, ধাপে ধাপে প্রক্রিয়ায় বদলে দেয়৤</p>\n<h2 id=\"deadline-pressure\">সময়সীমার চাপে কাজ করা</h2>\n<p>আবেদনে প্রায়ই কঠোর সময়সীমা থাকে৤ ফরম বন্ধের আগের রাত কমপ্রেশন শেখার সবচেয়ে খারাপ সময়৤</p>\n<p>ছবি আর নথি আগেই তৈরি করুন৤ কয়েক দিন আগে কমপ্রেস করে আবেদনের নামে ফোল্ডারে রাখুন৤</p>\n<p>সময়সীমার একদিন আগে আপলোড পরীক্ষা করুন৤ পোর্টাল ফাইল বাতিল করলে ঠিক করার সময় থাকবে৤</p>\n<p>টুল বুকমার্ক করে রাখুন আর অরিজিনাল হাতের কাছে রাখুন৤ প্রস্তুত আবেদনকারী মিনিটে শেষ করেন, আর অন্যরা আতঙ্কে থাকেন৤</p>\n<p>সময়সীমার কাছাকাছি পোর্টাল বন্ধ হয়ে গেলে শান্ত থাকুন আর আবার চেষ্টা করুন৤ সিস্টেম প্রায়ই ফিরে আসে, আর প্রস্তুত ফাইল সেট মানে একটা কাজের সময়ই যথেষ্ট৤</p>\n<h2 id=\"reusing-photos\">অনেক আবেদনে একই পোর্টাল ছবি ব্যবহার করা</h2>\n<p>ভালো পোর্টাল ছবি অনেক আবেদনে কাজে আসতে পারে৤ একবার পরিষ্কার 200KB হেডশট পেয়ে গেলে নিয়ম অনুমতি দিলে যেকোনো জায়গায় আবার ব্যবহার করুন৤</p>\n<p>প্রতিবার নিয়ম যাচাই করুন৤ এক পোর্টাল 200KB চাইলে আরেকটা 100KB চাইতে পারে, আর একই ফাইল দুটোতে চলবে না৤</p>\n<p>এক-দুই বছর পর ছবি আপডেট করুন৤ আপনার মতো আর দেখায় না এমন ছবি যাচাইয়ে সমস্যা করতে পারে৤</p>\n<p>কমপ্রেস করা ছবি যে আবেদনের, তার সঙ্গেই রাখুন৤ ডাউনলোড ফোল্ডারে পড়ে থাকা ছবি হারিয়ে যাওয়ার অপেক্ষায় থাকে৤</p>\n<p>নিয়ম বদলালে অরিজিনাল থেকে নতুন করে কমপ্রেস করুন৤ পুরনো 200KB কপি আবার কমপ্রেস করবেন না, কারণ প্রতিটি রাউন্ড ক্ষতি যোগ করে৤</p>\n<h2 id=\"verification-steps\">পোর্টালে যাচাইয়ের ধাপ</h2>\n<p>অনেক পোর্টাল ছবি আইডি নথির সঙ্গে মিলিয়ে যাচাই করে৤ ছবিতে একই ব্যক্তি পরিষ্কার দেখা যাওয়া উচিত, ভারী ফিল্টার বা এডিট ছাড়া৤</p>\n<p>কমপ্রেসের আগে বিউটি ফিল্টার এড়িয়ে চলুন৤ মসৃণ করা ত্বক আর বদলে যাওয়া বৈশিষ্ট্য যাচাইয়ে ব্যর্থ হতে পারে আর আবেদন দেরি করাতে পারে৤</p>\n<p>পটভূমি সাদা আর আলো সমান রাখুন৤ কিছুই মনোযোগ না সরালে যাচাই সিস্টেম মুখ ভালোভাবে পড়তে পারে৤</p>\n<p>যাচাই ব্যর্থ হলে পুরনো ছবি এডিট না করে আবার তুলুন৤ মেরামত করা ছবির চেয়ে নতুন, সৎ ছবি বেশি নির্ভরযোগ্যভাবে পাস করে৤</p>\n<p>মনে রাখবেন কমপ্রেশন পরিচয় বদলায় না৤ মুখ তীক্ষ্ণ থাকলে পরিষ্কার 200KB ছবি অরিজিনালের মতোই যাচাই হয়৤</p>\n<h2 id=\"long-term-habits\">আবেদনের ছবির দীর্ঘমেয়াদি অভ্যাস</h2>\n<p>ডিভাইসে ব্যবহারের জন্য তৈরি পোর্টাল ছবি রাখুন৤ পরিষ্কার হেডশট, আগেই 200KB-তে কমপ্রেস করা, নতুন আবেদনকে পাঁচ মিনিটের কাজে বদলে দেয়৤</p>\n<p>চেহারা বদলালে ছবি নতুন করুন৤ তিন বছর আগের ছবি যাচাইয়ে বিভ্রান্তি করতে পারে, যদিও প্রযুক্তিগতভাবে বৈধ৤</p>\n<p>অরিজিনাল কমপ্রেস করা কপির পাশেই রাখুন৤ অরিজিনালই মাস্টার, আর প্রতিটি কমপ্রেস করা সংস্করণ সেখান থেকেই আসা উচিত৤</p>\n<p>ঘন ঘন ব্যবহার করা পোর্টালগুলোর নিয়ম লিখে রাখুন৤ সীমা আর ফরম্যাটের ছোট তালিকা প্রতিবার ছোট ছোট অক্ষর পড়া থেকে বাঁচায়৤</p>\n<p>ভালো অভ্যাস জমে বড় হয়৤ প্রতিটি আবেদন সহজ হয়, আর ফাইল আগেই তৈরি থাকলে সময়সীমার চাপ মিলিয়ে যায়৤</p>\n<p>সাধারণ 200KB গাইডের জন্য পড়ুন <a href=\"/bn/blog/image-200kb-te-compress-korun-guide\">200KB-তে ছবি কমপ্রেস: সম্পূর্ণ গাইড</a>৤ হাতে-কলমে ধাপের জন্য দেখুন <a href=\"/bn/blog/image-200kb-te-compress-kivabe-korben\">ছবি 200KB-তে কীভাবে কমপ্রেস করবেন</a>৤</p>\n";

